import { useContext } from '@vean/aria/composables';
import { UI_CONFIG_PROVIDER_CONTEXT_KEY } from '../../constants';
import type { ConfigProviderContext } from './types';

/**
 * UI-level ConfigProvider context.
 *
 * Separate from the Aria `ConfigProvider` context (different inject key): it
 * carries the resolved theme options so consumers can read the active theme
 * without prop drilling.
 */
export const [provideConfigProviderContext, useConfigProvider] = useContext<ConfigProviderContext>({
  name: 'UIConfigProvider',
  key: UI_CONFIG_PROVIDER_CONTEXT_KEY
});

import type { ConfigProviderProps as _ConfigProviderProps } from '@vean/aria/config-provider';
import type { ProgressProviderProps } from '@vean/aria/progress';
import type { ThemeOptions } from '@vean/theme';
import type { ThemeEnvelopeInput } from '@vean/theme/storage';
import type { ThemePresetColors, ThemePresetInput } from '@/theme/types';
import type { ToastProviderProps } from '../toast/types';

/**
 * UI-level theme options accepted by `SConfigProvider`.
 *
 * The engine's `ThemeOptions` carries `overrides` for inline token overrides.
 * The provider additionally accepts a `preset` input — either an inline
 * mode-split override or a `{ name }` reference to a stored preset. The
 * provider resolves named references to their colors and materializes the
 * result as `overrides` before handing the options to the engine, so the
 * engine only ever receives resolved options.
 */
export type ConfigProviderThemeOptions = ThemeOptions & {
  /**
   * A custom color preset: either an inline mode-split override (light/dark
   * partial tokens) or a `{ name }` reference to a stored preset. Resolved to
   * `overrides` before the engine resolves the map.
   */
  preset?: ThemePresetInput;
};

export interface IconifyOptions {
  /**
   * The default width of the icon.
   *
   * @defaultValue '1.25em'
   */
  width?: string;
  /**
   * The default height of the icon.
   *
   * @defaultValue '1.25em'
   */
  height?: string;
}

/**
 * Properties for the ConfigProvider component.
 */
export interface ConfigProviderProps extends _ConfigProviderProps {
  /** The theme options. */
  theme?: ConfigProviderThemeOptions;
  /** The iconify options. */
  iconify?: IconifyOptions;
  /** The global top progress configuration of your application. */
  progress?: Partial<ProgressProviderProps>;
  /** The global toast configuration of your application. This will be inherited by the related components. */
  toast?: Partial<ToastProviderProps>;
  /**
   * Whether to use custom toast rendering. If set to `true`, the `ToastProvider` will not render the default toast UI, and you can import `ToastProvider` component to render custom toast UI.
   *
   * @default false
   */
  customToast?: boolean;
  /**
   * Whether to enable persisted theme reading from localStorage.
   *
   * When disabled (default), the ConfigProvider only consumes the explicit
   * `theme` prop and never reads or writes any storage, keeping the current
   * behavior. When enabled, the persisted theme envelope fills in keys not
   * explicitly provided by `theme`, and changes are written back through a
   * single debounced writer.
   *
   * @defaultValue false
   */
  persistTheme?: boolean;
  /**
   * The persisted theme envelope injected from the server.
   *
   * Used during SSR to render the same theme the client persisted; on the
   * client the localStorage envelope is the source of truth.
   *
   * @type ThemeEnvelopeInput
   */
  themeConfig?: ThemeEnvelopeInput;
  /**
   * The server-side custom theme preset registry resolver.
   *
   * Maps a stored preset name to its definition so SSR can render custom
   * presets without localStorage access. Only used when `persistTheme` is
   * enabled on the server; on the client the presets table (carried by the
   * theme envelope) is the source of truth.
   *
   * @param name The stored preset name to resolve.
   */
  presetProvider?: (name: string) => ThemePresetColors | null | undefined;
  /**
   * Whether the component is running in a server environment.
   *
   * The UI library is pre-built, so `import.meta.env.SSR` is baked at build
   * time and cannot detect the consumer's runtime. This defaults to runtime
   * detection (`typeof window === 'undefined'`), and can be overridden with
   * the app's own flag (e.g. Nuxt's `import.meta.server`) when the app is
   * bundled for both server and client.
   *
   * @defaultValue isServerRuntime()
   */
  isServer?: boolean;
}

/**
 * Context for the ConfigProvider component: a plain shallow-readonly snapshot of the props.
 */
export type ConfigProviderContext = Readonly<ConfigProviderProps>;

export type { ThemeOptions, ThemePresetColors };

export { default as SConfigProvider } from './config-provider.vue';
export { useConfigProvider } from './context';
export { useTheme } from './use-theme';

export type * from '@vean/aria/config-provider';
export type { ConfigProviderProps, ConfigProviderThemeOptions, IconifyOptions, ThemeOptions } from './types';
export type { ThemeContext } from './use-theme';

import { computed, onMounted, onUnmounted, watch } from 'vue';
import type { ComputedRef } from 'vue';
import { THEME_STORAGE_KEY, THEME_STYLE_ID, createThemeWriter } from '@vean/theme/storage';
import { buildThemeCss } from '../../theme/adapter';
import type { ConfigProviderProps } from './types';
import { createThemeContext, provideThemeContext } from './use-theme';
import type { ConfigProviderThemeContext } from './use-theme';

/**
 * Wire the ConfigProvider theme runtime.
 *
 * The provider owns exactly three side effects — the derived CSS, the single
 * `<style id="vean-theme">` node, and the theme envelope — so each one gets its
 * own hook below and this function only states the order they start in. Keeping
 * the context opaque here is the point: nothing in the DOM layer needs to reach
 * into the theme state, they only exchange the derived CSS.
 */
export function useConfigProviderTheme(props: ConfigProviderProps) {
  const themeContext = createThemeContext(props);

  provideThemeContext(themeContext);

  const themeCss = useThemeStyle(props, themeContext);

  useThemeEnvelope(props, themeContext, themeCss);

  // `commitThemeConfig` 是 `setThemeState` 的对外名字：写回持久化主题配置并同步内存状态，
  // 使下游主题派生无需重读存储。通过 `defineExpose` 暴露给应用层。
  return { commitThemeConfig: themeContext.setThemeState };
}

/**
 * Derive the runtime CSS and keep the one runtime style element in sync.
 *
 * **Style application**: the runtime owns exactly one `<style id="vean-theme">`
 * in `<head>`. The first-paint script may have created it (with the persisted
 * snapshot); the provider adopts that element, or creates it when absent, and
 * keeps its content in sync. Nothing is rendered into the component tree, so
 * there is no server/client style-content mismatch and no `!important` dance —
 * precedence comes from specificity (the static default layer ships
 * `:where(...)`-weakened, docs/design/theme.md §6.1 / §6.3).
 */
function useThemeStyle(props: ConfigProviderProps, themeContext: ConfigProviderThemeContext): ComputedRef<string> {
  const themeCss = computed(() => buildThemeCss(themeContext.theme.value));
  const styleHolder = createStyleElementHolder();

  const applyCss = (): void => {
    const element = styleHolder.acquire(props.nonce);

    if (element) {
      element.textContent = themeCss.value;
    }
  };

  // 变更即时应用；首帧由挂载补一次（`watch` 不带 immediate 时不会自己跑）
  watch(themeCss, applyCss);
  onMounted(applyCss);

  return themeCss;
}

/**
 * Own the theme envelope: one key, one debounced writer, one cross-tab reader.
 *
 * **Persistence**: the derived payload (options + mode + style snapshot + custom
 * presets) goes into `__VEAN_THEME` through a single debounced writer; the theme
 * context itself writes nothing. preset 表与已应用 preset 同信封携带：写入方
 * 只有这里一处，不存在多写者竞争。
 *
 * **Lifecycle**: mount subscribes to cross-tab storage, unmount unsubscribes and
 * flushes the pending write. Both live in one hook, so the order — and the fact
 * that there is exactly one of each — is visible in a single place.
 */
function useThemeEnvelope(
  props: ConfigProviderProps,
  themeContext: ConfigProviderThemeContext,
  themeCss: ComputedRef<string>
): void {
  const { theme, mode, customPresets, appliedPresetName, refreshThemeConfig } = themeContext;

  const writer = createThemeWriter();

  watch(
    [themeCss, mode, customPresets, appliedPresetName],
    () => {
      if (!props.persistTheme || typeof document === 'undefined') {
        return;
      }

      writer.write({
        options: theme.value,
        mode: mode.value,
        style: themeCss.value,
        presets: customPresets.value,
        ...(appliedPresetName.value ? { appliedPreset: appliedPresetName.value } : {})
      });
    },
    { immediate: true }
  );

  // 跨标签页同步：storage 事件（其他标签页写入主题信封）触发整体重读 ——
  // options / mode / presets / applied preset 一起刷新并重派生。
  const handleStorage = (event: StorageEvent): void => {
    if (event.key === THEME_STORAGE_KEY) {
      refreshThemeConfig();
    }
  };

  onMounted(() => {
    if (props.persistTheme) {
      window.addEventListener('storage', handleStorage);
    }
  });

  onUnmounted(() => {
    // 未开启持久化时从未注册，移除是幂等的空操作
    window.removeEventListener('storage', handleStorage);
    writer.flush();
  });
}

/**
 * A lazily created holder for the runtime style element.
 *
 * The element is *not* rendered by the component (a head element cannot be
 * rendered from the app tree without a head manager), so the provider looks it
 * up — the first-paint script may already have created it — and creates it once
 * when missing. Later calls return the live element, so a theme change after
 * hydration writes to the same node the script built.
 */
function createStyleElementHolder(): { acquire: (nonce?: string) => HTMLStyleElement | null } {
  let element: HTMLStyleElement | null = null;

  const acquire = (nonce?: string): HTMLStyleElement | null => {
    if (typeof document === 'undefined') {
      return null;
    }

    element ??= adoptOrCreateStyleElement();

    // CSP 下由脚本创建的元素同样需要 nonce（'nonce-…' 来源的 style-src）
    if (nonce && !element.getAttribute('nonce')) {
      element.setAttribute('nonce', nonce);
    }

    return element;
  };

  return { acquire };
}

/** Reuse the element the first-paint script built, otherwise create and append one. */
function adoptOrCreateStyleElement(): HTMLStyleElement {
  const existing = document.getElementById(THEME_STYLE_ID);

  if (existing instanceof HTMLStyleElement) {
    return existing;
  }

  const element = document.createElement('style');

  element.id = THEME_STYLE_ID;
  document.head.appendChild(element);

  return element;
}

import { computed, onUnmounted, reactive, ref, watch } from 'vue';
import type { ComputedRef, Ref, ShallowRef, WritableComputedRef } from 'vue';
import { useContext } from '@vean/aria/composables';
import { DEFAULT_OPTIONS } from '@vean/theme';
import type {
  PaletteKey,
  ThemeMode,
  ThemeModePreference,
  ThemeOptions,
  ThemeRadiusValue,
  ThemeSizeValue,
  ThemeSpacingValue
} from '@vean/theme';
import { isServerRuntime } from '@vean/theme/ssr';
import { readThemeEnvelope } from '@vean/theme/storage';
import type { ThemeEnvelopeInput } from '@vean/theme/storage';
import type { ThemePresetColors, ThemeSettingsState } from '@/theme';
import {
  mergePersistedState,
  replaceState,
  resolvePresetColors,
  resolveThemeOptions,
  syncDocumentMode
} from './shared';
import type { ConfigProviderProps } from './types';

/**
 * The reactive theme context exposed by `SConfigProvider`.
 *
 * It owns the persistable theme state (`base` / `primary` / `radius` / `size` /
 * `spacing` / `mode`), the custom preset management, and the effective `theme`
 * derived for the provider. Consumers read it via `useTheme()` to drive their own
 * theme UI without prop drilling or app-level state stores.
 */
export interface ThemeContext {
  /** The base color palette key. */
  base: WritableComputedRef<PaletteKey>;
  /** The primary color palette key. */
  primary: WritableComputedRef<PaletteKey>;
  /** The border radius. */
  radius: WritableComputedRef<ThemeRadiusValue>;
  /** The component size / density. */
  size: WritableComputedRef<ThemeSizeValue>;
  /** The spacing grid unit multiplier (padding / margin / gap). */
  spacing: WritableComputedRef<ThemeSpacingValue>;
  /** The color scheme preference (`light` / `dark` / `auto`). */
  mode: WritableComputedRef<ThemeModePreference>;
  /** The effective (resolved) color scheme: `auto` follows the OS preference. */
  effectiveMode: ComputedRef<ThemeMode>;
  /** Set the border radius. */
  setRadius: (value: ThemeRadiusValue) => void;
  /** Set the component size / density. */
  setSize: (value: ThemeSizeValue) => void;
  /** Set the spacing grid unit multiplier. */
  setSpacing: (value: ThemeSpacingValue) => void;
  /** Set the color scheme preference. */
  setMode: (value: ThemeModePreference) => void;
  /** The persisted custom theme presets table. */
  customPresets: Ref<Record<string, ThemePresetColors>>;
  /** The currently applied custom preset name, if any. */
  appliedPresetName: ShallowRef<string | null>;
  /** Save the current primary color as a custom preset. */
  savePreset: (name: string) => boolean;
  /** Remove a custom preset. */
  removePreset: (name: string) => boolean;
  /** Apply a custom preset by name. */
  applyPreset: (name: string) => void;
  /** Clear the applied custom preset. */
  resetPreset: () => void;
  /** Overwrite the full persistable theme state (options + mode). */
  setThemeState: (config: ThemeSettingsState) => void;
  /** The effective theme merged from the internal state and the `theme` prop. */
  theme: ComputedRef<ThemeOptions>;
}

export const [provideThemeContext, useThemeConsumer] = useContext<ThemeContext>('UiThemeContext');

export const useTheme = (consumerName?: string | null, defaultValue?: ThemeContext) =>
  useThemeConsumer(consumerName ?? 'ThemeConsumer', defaultValue);

/** The internal theme context held by `SConfigProvider` (adds storage helpers). */
export type ConfigProviderThemeContext = ThemeContext & {
  /**
   * Re-read the persisted envelope (options / mode / presets / applied preset)
   * from storage and apply it (cross-tab sync).
   */
  refreshThemeConfig: () => void;
};

/** The persisted source a fresh provider starts from, if any. */
function readPersistedTheme(props: ConfigProviderProps, isServer: boolean): ThemeEnvelopeInput | null {
  if (!props.persistTheme) {
    return null;
  }

  // 显式注入的 themeConfig（SSR）优先，避免读取 localStorage
  if (props.themeConfig) {
    return props.themeConfig;
  }

  // 服务端没有 localStorage：首帧由内联脚本（createThemeInitScript）在客户端应用
  return isServer ? null : readThemeEnvelope();
}

/**
 * Expose one field of the shared state as a writable computed.
 *
 * The getter falls back per field, so the state may hold only what was actually
 * persisted (see `mergePersistedState`) — that is what keeps every lower-priority
 * source, such as the deprecated `size` prop, reachable.
 */
function createStateField<K extends keyof typeof DEFAULT_OPTIONS>(
  state: ThemeSettingsState,
  key: K
): WritableComputedRef<NonNullable<ThemeSettingsState[K]>> {
  return computed({
    get: () => (state[key] ?? DEFAULT_OPTIONS[key]) as NonNullable<ThemeSettingsState[K]>,
    set: value => {
      state[key] = value;
    }
  });
}

/** Track the OS dark preference. `null` on the server, where `matchMedia` does not exist. */
function createSystemDarkQuery(): MediaQueryList | null {
  if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
    return null;
  }

  return window.matchMedia('(prefers-color-scheme: dark)');
}

/**
 * Create the theme context for a `SConfigProvider` instance.
 *
 * The persistable theme state is initialized once from the persisted source
 * (the injected `themeConfig` on the server, the theme envelope on the client)
 * and kept in sync on every change, so the theme survives across refreshes and
 * matches between server and client rendering.
 *
 * **Persistence**: the context itself writes nothing — the provider's single
 * envelope writer (see `useConfigProviderTheme`) watches the derived state and
 * owns every write to the one storage key.
 */
export function createThemeContext(props: ConfigProviderProps): ConfigProviderThemeContext {
  const isServer = props.isServer ?? isServerRuntime();
  const persisted = readPersistedTheme(props, isServer);

  // —— 持久化状态：单一 reactive 源，字段逐个以可写 computed 暴露 ——
  const themeState = reactive<ThemeSettingsState>(mergePersistedState(persisted));

  const base = createStateField(themeState, 'base');
  const primary = createStateField(themeState, 'primary');
  const radius = createStateField(themeState, 'radius');
  const size = createStateField(themeState, 'size');
  const spacing = createStateField(themeState, 'spacing');
  // `mode` 不是引擎选项：DEFAULT_OPTIONS 里没有它，单独回落 `light`。
  // JSON 会丢掉 undefined 字段，所以持久化信封里不会出现缺失的 mode。
  const mode = computed<ThemeModePreference>({
    get: () => themeState.mode ?? 'light',
    set: value => {
      themeState.mode = value;
    }
  });

  // —— auto 模式的系统偏好解析：跟踪 `prefers-color-scheme`，SSR 下无
  //    matchMedia 时回退为 light，首帧由 createThemeInitScript 在浏览器处理 ——
  const systemDarkQuery = createSystemDarkQuery();
  const systemDark = ref(systemDarkQuery?.matches ?? false);

  const onSystemColorChange = (event: MediaQueryListEvent): void => {
    systemDark.value = event.matches;
  };

  systemDarkQuery?.addEventListener('change', onSystemColorChange);

  onUnmounted(() => {
    systemDarkQuery?.removeEventListener('change', onSystemColorChange);
  });

  /** `auto` 解析为系统偏好；显式 `light` / `dark` 原样返回 */
  const effectiveMode = computed<ThemeMode>(() =>
    mode.value === 'auto' ? (systemDark.value ? 'dark' : 'light') : mode.value
  );

  // —— 自定义 preset（随主题信封持久化；persistTheme 关闭时仅内存态）——
  const customPresets = ref<Record<string, ThemePresetColors>>(
    (persisted?.presets as Record<string, ThemePresetColors> | undefined) ?? {}
  );
  const appliedPresetName = ref<string | null>(persisted?.appliedPreset ?? null);

  // —— 有效主题：显式 theme prop 覆盖内部状态 ——
  const theme = computed<ThemeOptions>(() =>
    resolveThemeOptions({
      propTheme: props.theme,
      state: themeState,
      preset: resolvePresetColors({
        presetInput: props.theme?.preset,
        appliedName: appliedPresetName.value,
        persist: !!props.persistTheme,
        isServer,
        presets: customPresets.value,
        presetProvider: props.presetProvider
      })
    })
  );

  const activeDarkSelector = computed(() => theme.value.darkSelector ?? DEFAULT_OPTIONS.darkSelector);

  const savePreset = (name: string): boolean => {
    const preset: ThemePresetColors = {
      light: { primary: `${primary.value}.600`, ring: `${primary.value}.500` },
      dark: { primary: `${primary.value}.400`, ring: `${primary.value}.300` }
    };

    customPresets.value = { ...customPresets.value, [name]: preset };
    appliedPresetName.value = name;

    return true;
  };

  const removePreset = (name: string): boolean => {
    if (!(name in customPresets.value)) {
      return false;
    }

    const { [name]: _removed, ...remaining } = customPresets.value;

    customPresets.value = remaining;

    if (appliedPresetName.value === name) {
      appliedPresetName.value = null;
    }

    return true;
  };

  /**
   * 跨标签页同步：另开标签页写入主题信封后重读并应用到内存状态 ——
   * options / mode / presets / applied preset 一起刷新，`theme` 随之重派生。
   * 读不到信封（被清空 / 无权访问）时不改动任何状态。`themeConfig` 注入（SSR）时不重读。
   *
   * `Object.assign` 不够：`JSON.stringify` 丢掉 `undefined` 字段，所以「清除
   * override」写出的信封里没有 `overrides`，而目标标签页的旧值会残留。整体替换
   * 才会让信封的缺席真正等于清除。
   */
  const refreshThemeConfig = (): void => {
    if (!props.persistTheme || props.themeConfig) {
      return;
    }

    const envelope = readThemeEnvelope();

    if (!envelope) {
      return;
    }

    replaceState(themeState, mergePersistedState(envelope));
    customPresets.value = (envelope.presets as Record<string, ThemePresetColors> | undefined) ?? {};
    appliedPresetName.value = envelope.appliedPreset ?? null;
  };

  // —— 暗色模式 class + color-scheme 同步（首帧前由 createThemeInitScript 应用，
  //    此处幂等并负责运行中切换）。监听解析后的 darkSelector：持久化状态里改了
  //    选择器口径时也要重新对齐，而不是一直沿用挂载时的 prop。
  watch([effectiveMode, activeDarkSelector], ([value, darkSelector]) => syncDocumentMode(value, darkSelector), {
    immediate: true
  });

  return {
    base,
    primary,
    radius,
    size,
    spacing,
    mode,
    effectiveMode,
    setRadius: value => {
      radius.value = value;
    },
    setSize: value => {
      size.value = value;
    },
    setSpacing: value => {
      spacing.value = value;
    },
    setMode: value => {
      mode.value = value;
    },
    customPresets,
    appliedPresetName,
    savePreset,
    removePreset,
    applyPreset: name => {
      appliedPresetName.value = name;
    },
    resetPreset: () => {
      appliedPresetName.value = null;
    },
    theme,
    setThemeState: config => {
      Object.assign(themeState, config);
    },
    refreshThemeConfig
  };
}

export * from './attr';
export * from './common';
export * from './components';

import type { IconValue } from '@vean/aria';
import type { IconProps as IconifyIconProps } from '@iconify/vue';

/**
 * Properties for the Icon component.
 */
export interface IconProps extends Omit<IconifyIconProps, 'icon'> {
  /**
   * Icon rendered by the component.
   */
  icon: IconValue;
  /**
   * Whether the icon is hidden from assistive technology.
   *
   * Defaults to `true` for decorative icons. Set to `false` or provide `ariaLabel` / `ariaLabelledby` to expose the icon.
   */
  ariaHidden?: boolean;
  /**
   * Accessible label for the icon. When provided, `aria-hidden` is not set so the label is announced.
   */
  ariaLabel?: string;
  /**
   * ID of an element that labels the icon. When provided, `aria-hidden` is not set so the label is announced.
   */
  ariaLabelledby?: string;
}

export type { IconValue };

import type { SemanticToken, TokenOverride } from '@vean/theme';

export type { ThemeSize } from '@vean/theme';

/**
 * the component `color` prop vocabulary — the v2 role families a component can
 * paint with (fills, statuses, carbon). Maps 1:1 onto the style recipes.
 */
export type ThemeColor = 'primary' | 'secondary' | 'accent' | 'destructive' | 'success' | 'warning' | 'info' | 'carbon';

/**
 * the color payload of a custom theme preset: light/dark token overrides in the
 * engine's own vocabulary (`primary: 'indigo.600'`, complete colors, …).
 */
export interface ThemePresetColors {
  light: Partial<Record<SemanticToken, TokenOverride>>;
  dark?: Partial<Record<SemanticToken, TokenOverride>>;
}

/** a preset input: inline colors, or a `{ name }` reference to a stored preset. */
export type ThemePresetInput = ThemePresetColors | { name: string };

import type { ToastProviderProps as _ToastProviderProps, ToastUi } from '@vean/aria/toast';
import type { ThemeSize } from '@/theme';

/**
 * Properties for the ToastProvider component.
 */
export interface ToastProviderProps extends _ToastProviderProps {
  /**
   * Visual size of the component.
   */
  size?: ThemeSize;
  /**
   * Per-slot class overrides for the component.
   */
  ui?: ToastUi;
}

import { DEFAULT_OPTIONS, emitThemeCss, resolveThemeMap } from '@vean/theme';
import type { EmitThemeOptions, ThemeOptions } from '@vean/theme';

/**
 * Bridge from the runtime theme state to the token engine.
 *
 * The runtime theme context produces engine `ThemeOptions` directly, so the
 * bridge only centralizes *how* the alias block is emitted: the options travel
 * to `resolveThemeMap` untouched and the emit options follow the options, so
 * the runtime block, the preset preflight and the first-paint snapshot all use
 * the same prefix / selector / format decisions.
 */
export function buildThemeCss(options: ThemeOptions, emit?: EmitThemeOptions): string {
  return emitThemeCss(resolveThemeMap(options), {
    prefix: options.prefix ?? DEFAULT_OPTIONS.prefix,
    styleTarget: options.styleTarget,
    darkSelector: options.darkSelector,
    format: options.format,
    ...emit
  });
}

export * from './config';
export * from './use-theme-settings';
export * from './use-theme-variants';

export type * from './types';
export { buildThemeCss } from './adapter';

import { DEFAULT_OPTIONS, darkClassName, resolveDocumentColorScheme } from '@vean/theme';
import type { DarkSelectorValue, ThemeMode, ThemeOptions, ThemeOverrides } from '@vean/theme';
import type { ThemeEnvelopeInput } from '@vean/theme/storage';
import type { ThemePresetColors, ThemePresetInput, ThemeSettingsState } from '@/theme';
import type { ConfigProviderThemeOptions } from './types';

/**
 * Pure theme helpers for `SConfigProvider`.
 *
 * Everything here is a plain function of its arguments: no `ref`, no lifecycle,
 * no component scope. The composables in `use-theme.ts` own the reactive state
 * and hand it in, which is what keeps the merge rules ("prop → state → default")
 * readable and individually testable.
 */

/**
 * `*{transition:none}` injected for exactly one reflow while the dark class
 * flips. Without it a component carrying `transition-all` (a button, say) fades
 * its colors 150ms late against a background that already switched.
 */
const TRANSITION_SUPPRESS_CSS =
  '*,*::before,*::after{-webkit-transition:none!important;-moz-transition:none!important;-o-transition:none!important;-ms-transition:none!important;transition:none!important}';

/**
 * whether a preset input is an inline color preset (mode-split, carries
 * `light`). A reference-only input carries just `name` and no `light`.
 */
export function isInlineColorPreset(preset: ThemePresetInput | undefined): preset is ThemePresetColors {
  return !!preset && 'light' in preset;
}

/**
 * Merge a persisted envelope into the settings state.
 *
 * Only what the envelope actually carried lands here — engine defaults are NOT
 * injected, because `resolveThemeOptions` already falls back per field at read
 * time. Pre-filling them would make the state shadow every lower-priority
 * source (that is how the deprecated `size` prop became dead code).
 */
export function mergePersistedState(envelope: ThemeEnvelopeInput | null): ThemeSettingsState {
  return {
    ...envelope?.options,
    ...(envelope?.mode ? { mode: envelope.mode } : {})
  };
}

/**
 * Replace the state in place, dropping fields the incoming state lacks.
 *
 * `Object.assign` keeps keys it is not given, which makes absence ambiguous: an
 * envelope written after "clear all overrides" carries no `overrides` key (JSON
 * drops `undefined`), so assign leaves the previous tag's overrides in place and
 * the clear never propagates. Deleting the stale keys first is what makes the
 * absence mean "unset" rather than "unchanged".
 */
export function replaceState(target: ThemeSettingsState, next: ThemeSettingsState): void {
  for (const key of Object.keys(target) as (keyof ThemeSettingsState)[]) {
    if (!(key in next)) {
      delete target[key];
    }
  }

  Object.assign(target, next);
}

/** Materialize a preset's colors as the engine's `overrides` payload. */
export function presetToOverrides(preset: ThemePresetColors | undefined): ThemeOverrides | undefined {
  if (!preset) {
    return undefined;
  }

  return {
    light: preset.light,
    ...(preset.dark ? { dark: preset.dark } : {})
  };
}

/** Input of `resolvePresetColors`. */
export interface ResolvePresetInput {
  /** the `theme.preset` prop: inline colors, or a `{ name }` reference. */
  presetInput?: ThemePresetInput;
  /** the name committed through `applyPreset` / `savePreset`. */
  appliedName: string | null;
  /** whether the provider is allowed to read the persisted envelope. */
  persist: boolean;
  isServer: boolean;
  /** the in-memory preset table (client). */
  presets: Record<string, ThemePresetColors>;
  /** the app-registered resolver used during SSR. */
  presetProvider?: (name: string) => ThemePresetColors | null | undefined;
}

/**
 * Resolve the colors of the preset that should be applied, or `undefined` when
 * the built-in palette is what renders.
 *
 * Resolution order: an inline `theme.preset` (self-contained, always wins), then
 * the name from `theme.preset` or the applied preset. A named reference is only
 * resolvable when persistence is on — that is where the preset table lives — and
 * it resolves through the injected provider on the server, the memory table on
 * the client.
 */
export function resolvePresetColors(input: ResolvePresetInput): ThemePresetColors | undefined {
  const { presetInput, appliedName, persist, isServer, presets, presetProvider } = input;

  if (isInlineColorPreset(presetInput)) {
    return presetInput;
  }

  const name = presetInput?.name ?? appliedName;

  if (!name || !persist) {
    return undefined;
  }

  const preset = isServer ? (presetProvider?.(name) ?? undefined) : presets[name];

  if (!preset && isServer) {
    // a missing preset on the server is a real defect: the client resolves it
    // from its own table, so SSR and hydration would disagree on the palette.
    console.warn(`[SConfigProvider] theme preset "${name}" not found, falling back to built-in colors.`);
  }

  return preset;
}

/** Input of `resolveThemeOptions`. */
export interface ResolveThemeOptionsInput {
  /** the `theme` prop. */
  propTheme?: ConfigProviderThemeOptions;
  /** the provider's persistable state. */
  state: ThemeSettingsState;
  /** the resolved preset colors, if any. */
  preset?: ThemePresetColors;
}

/**
 * Compose the effective engine options.
 *
 * Precedence is per field: the `theme` prop (explicit caller intent), then the
 * provider state (persisted or committed), then the engine default. `overrides`
 * prefers an explicit `overrides` over a preset's colors, so a caller can always
 * hand-pick tokens on top of a preset.
 */
export function resolveThemeOptions(input: ResolveThemeOptionsInput): ThemeOptions {
  const { propTheme: themeProp = {}, state, preset } = input;

  return {
    base: themeProp.base ?? state.base ?? DEFAULT_OPTIONS.base,
    primary: themeProp.primary ?? state.primary ?? DEFAULT_OPTIONS.primary,
    feedback: themeProp.feedback ?? state.feedback,
    overrides: themeProp.overrides ?? state.overrides ?? presetToOverrides(preset),
    size: themeProp.size ?? state.size ?? DEFAULT_OPTIONS.size,
    radius: themeProp.radius ?? state.radius ?? DEFAULT_OPTIONS.radius,
    spacing: themeProp.spacing ?? state.spacing,
    // 字体族：引擎的三条 `--font-*` 字面量，改一只影响字族栈
    font: themeProp.font ?? state.font,
    format: themeProp.format ?? state.format,
    surfaceStyle: themeProp.surfaceStyle ?? state.surfaceStyle,
    borderOpacity: themeProp.borderOpacity ?? state.borderOpacity,
    // token 命名空间：`false` 是默认（与 shadcn 同名），字符串则给所有变量加前缀。
    // 漏掉这一项会让宿主的 prefix 选项静默失效：解析与发射必须同值。
    prefix: themeProp.prefix ?? state.prefix ?? DEFAULT_OPTIONS.prefix,
    styleTarget: themeProp.styleTarget ?? state.styleTarget,
    darkSelector: themeProp.darkSelector ?? state.darkSelector
  };
}

/**
 * Push a resolved mode onto the document: the inline `color-scheme` and the dark
 * class, with CSS transitions suppressed for the flip.
 *
 * `color-scheme` must be written here and not only via the class: the first-paint
 * script sets it as an **inline style** on `<html>`, and an inline style outranks
 * every selector — toggling only the class leaves the stale inline value winning
 * inside the `.dark` block, so UA-drawn surfaces (scrollbars, form controls,
 * canvas) stay light. Both writers go through `resolveDocumentColorScheme`, so
 * they agree by construction.
 *
 * Class precedence comes from `darkSelector`: `media` toggles nothing (the media
 * query already follows the OS), `class` toggles `dark`, any other selector is
 * used verbatim.
 */
export function syncDocumentMode(mode: ThemeMode, darkSelector: DarkSelectorValue): void {
  if (typeof document === 'undefined') {
    return;
  }

  document.documentElement.style.colorScheme = resolveDocumentColorScheme(mode, darkSelector);

  const darkClass = darkClassName(darkSelector);

  if (!darkClass) {
    return;
  }

  // 复刻 @vueuse/core useColorMode 的 disableTransition 手法：
  // 注入 `*{transition:none!important}` → 切 class → 强制 reflow → 移除
  const suppressTransitions = document.createElement('style');

  suppressTransitions.appendChild(document.createTextNode(TRANSITION_SUPPRESS_CSS));
  document.head.appendChild(suppressTransitions);

  document.documentElement.classList.toggle(darkClass, mode === 'dark');

  // 强制浏览器同步重算样式，确保禁用过渡的规则在 class 切换前生效
  void window.getComputedStyle(suppressTransitions).opacity;
  document.head.removeChild(suppressTransitions);
}

